package add_route

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "add_route"
	command.Identifiers = []string{"add-route"}
	command.Category = "Server System"
	command.Help = "Declare a new http route"
	command.LongDescription = "Writes sandbox/internal/routeslist/<name>/route.yaml — one path, Route, reading the whole request path against the trigger — and a stub InternalPureHandler.go, then runs build so the route's new.go (the api.Route that lands in Server.Routes) and entries.go (the Entries its handler is handed) are generated. priority and response-type are always written."
	command.Examples = []string{"add-route create-user --trigger /users --method POST --help \"Create a user\" --category Users"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "trigger",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "what the whole request path is compared against; an equal, prefix or regex trigger is normalized to start with / (defaults to /<name>)",
			Examples:    []string{"--trigger /users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger"},
		},
		{
			Id:          "trigger-type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "how the trigger is compared against the whole request path: equal, prefix, suffix or regex (defaults to equal)",
			Examples:    []string{"add-route logger --trigger / --trigger-type prefix --help 'logs every request' --category Server"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--trigger-type"},
		},
		{
			Id:          "method",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "an http method the route answers: GET, POST, PUT, PATCH, DELETE, HEAD or OPTIONS (repeatable; defaults to GET)",
			Examples:    []string{"--method POST"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--method", "-m"},
		},
		{
			Id:          "response-type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the Content-Type every response of the route carries (defaults to application/json)",
			Examples:    []string{"--response-type text/plain"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--response-type"},
		},
		{
			Id:          "help",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "one-line description of the route",
			Examples:    []string{"--help \"Create a user\""},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--help"},
		},
		{
			Id:          "category",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the heading the route is listed under in docs/Routes",
			Examples:    []string{"--category Users"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--category"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"add-route --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
		{
			Id:          "priority",
			Type:        "int",
			Required:    false,
			Array:       false,
			Description: "the rung this route runs on when several match one request: lowest first, and a route that writes no status hands the request on",
			Examples:    []string{"add-route logger --trigger / --trigger-type prefix --priority 0 --help 'logs every request' --category Server"},
			Default:     "0",
			HasDefault:  true,
			Identifiers: []string{"--priority"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "name",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route name (becomes the directory sandbox/internal/routeslist/<name> and its Go package)",
			Examples:    []string{"add-route create-user"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
